create policy "mvp1_mfa_verified_session" on public.plans as restrictive for all to authenticated using (array[(select auth.jwt()->>'aal')] <@ (select case when count(id)>0 then array['aal2'] else array['aal1','aal2'] end from auth.mfa_factors where user_id=(select auth.uid()) and status='verified')) with check (array[(select auth.jwt()->>'aal')] <@ (select case when count(id)>0 then array['aal2'] else array['aal1','aal2'] end from auth.mfa_factors where user_id=(select auth.uid()) and status='verified'));
